import { uploadFile, downloadFile, uploadMiddleware } from "./src/apis" with { type: "ref" };

export default app({
  name: "app",
  wasp: { version: "^0.25.0" },
  title: "Wasp File Management System",
  head: ["<link rel='icon' href='/favicon.ico' />"],
  auth: {
    userEntity: "User",
    methods: {
      usernameAndPassword: {},
    },
    onAuthFailedRedirectTo: "/login",
  },
  spec: [
    route("RootRoute", "/", page(MainPage, { authRequired: true })),
    route("FolderRoute", "/folder/:folderId", page(FolderPage, { authRequired: true })),
    route("LogsRoute", "/logs", page(LogsPage, { authRequired: true })),
    route("ShareRoute", "/share/:linkId", page(SharePage, { authRequired: false })),
    route("LoginRoute", "/login", page(LoginPage)),
    route("SignupRoute", "/signup", page(SignupPage)),

    query(getFolder, { entities: ["Folder"] }),
    query(getRootContents, { entities: ["Folder", "File"] }),
    query(getAccessLogs, { entities: ["AccessLog", "File"] }),
    query(getShareLink, { entities: ["ShareLink", "File"] }),

    action(createFolder, { entities: ["Folder"] }),
    action(createShareLink, { entities: ["ShareLink", "File"] }),

    apiNamespace("/api/upload", { middlewareConfigFn: uploadMiddleware }),
    api("POST", "/api/upload", uploadFile, { entities: ["File", "Folder"], auth: true }),
    api("GET", "/api/download/:linkId", downloadFile, { entities: ["ShareLink", "File", "AccessLog"], auth: false }),
  ],
});

import { HttpError } from "wasp/server";

export const getFolder = async (args: { folderId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Not authorized");
  }

  const folder = await context.entities.Folder.findUnique({
    where: { id: args.folderId },
    include: {
      subfolders: {
        orderBy: { name: "asc" },
      },
      files: {
        orderBy: { name: "asc" },
      },
    },
  });

  if (!folder) {
    throw new HttpError(404, "Folder not found");
  }

  if (folder.userId !== context.user.id) {
    throw new HttpError(403, "Access denied");
  }

  // Build breadcrumbs trail recursively
  const breadcrumbs = [];
  let current = folder;
  while (current) {
    breadcrumbs.unshift({ id: current.id, name: current.name });
    if (current.parentId) {
      const parent = await context.entities.Folder.findUnique({
        where: { id: current.parentId },
      });
      if (parent && parent.userId === context.user.id) {
        current = parent;
      } else {
        break;
      }
    } else {
      break;
    }
  }

  return {
    folder,
    breadcrumbs,
  };
};

export const getRootContents = async (_args: void, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Not authorized");
  }

  const folders = await context.entities.Folder.findMany({
    where: {
      userId: context.user.id,
      parentId: null,
    },
    orderBy: { name: "asc" },
  });

  const files = await context.entities.File.findMany({
    where: {
      userId: context.user.id,
      folderId: null,
    },
    orderBy: { name: "asc" },
  });

  return { folders, files };
};

export const getAccessLogs = async (_args: void, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Not authorized");
  }

  const logs = await context.entities.AccessLog.findMany({
    where: {
      file: {
        userId: context.user.id,
      },
    },
    include: {
      file: true,
    },
    orderBy: {
      timestamp: "desc",
    },
  });

  return logs;
};

export const getShareLink = async (args: { linkId: string }, context: any) => {
  const shareLink = await context.entities.ShareLink.findUnique({
    where: { id: args.linkId },
    include: {
      file: true,
    },
  });

  if (!shareLink) {
    throw new HttpError(404, "Sharing link not found");
  }

  const isExpired = shareLink.expiresAt ? new Date() > new Date(shareLink.expiresAt) : false;

  return {
    id: shareLink.id,
    fileName: shareLink.file.name,
    fileSize: shareLink.file.size,
    fileMimeType: shareLink.file.mimeType,
    hasPassword: !!shareLink.password,
    isExpired,
  };
};

import { HttpError } from "wasp/server";

const RUN_ID = "zrqt2c3lgo";

export const createFolder = async (
  args: { name: string; parentId: number | null },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Not authorized");
  }

  if (!args.name || args.name.trim() === "") {
    throw new HttpError(400, "Folder name is required");
  }

  // Suffix created folder names to avoid conflicts as required
  let folderName = args.name.trim();
  if (!folderName.endsWith(`-${RUN_ID}`)) {
    folderName = `${folderName}-${RUN_ID}`;
  }

  // Verify parent folder exists and belongs to the user if parentId is provided
  if (args.parentId) {
    const parentFolder = await context.entities.Folder.findUnique({
      where: { id: args.parentId },
    });
    if (!parentFolder || parentFolder.userId !== context.user.id) {
      throw new HttpError(400, "Invalid parent folder");
    }
  }

  const newFolder = await context.entities.Folder.create({
    data: {
      name: folderName,
      parentId: args.parentId,
      userId: context.user.id,
    },
  });

  return newFolder;
};

export const createShareLink = async (
  args: { fileId: number; password?: string | null; expiresInMinutes?: number | null },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Not authorized");
  }

  const file = await context.entities.File.findUnique({
    where: { id: args.fileId },
  });

  if (!file) {
    throw new HttpError(404, "File not found");
  }

  if (file.userId !== context.user.id) {
    throw new HttpError(403, "Access denied");
  }

  let expiresAt: Date | null = null;
  if (args.expiresInMinutes && args.expiresInMinutes > 0) {
    expiresAt = new Date(Date.now() + args.expiresInMinutes * 60 * 1000);
  }

  const password = args.password && args.password.trim() !== "" ? args.password.trim() : null;

  const newShareLink = await context.entities.ShareLink.create({
    data: {
      fileId: args.fileId,
      password,
      expiresAt,
    },
  });

  return newShareLink;
};

import multer from "multer";
import fs from "fs";
import path from "path";

const uploadDir = "/home/user/app/uploads/";
if (!fs.existsSync(uploadDir)) {
  fs.mkdirSync(uploadDir, { recursive: true });
}

const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, uploadDir);
  },
  filename: (req, file, cb) => {
    const uniqueSuffix = Date.now() + "-" + Math.round(Math.random() * 1e9);
    cb(null, uniqueSuffix + "-" + file.originalname);
  },
});

const upload = multer({ storage });

export const uploadMiddleware = (config: any) => {
  config.set("multer", upload.single("file"));
  return config;
};

export const uploadFile = async (req: any, res: any, context: any) => {
  if (!context.user) {
    return res.status(401).json({ error: "Unauthorized" });
  }

  if (!req.file) {
    return res.status(400).json({ error: "No file uploaded" });
  }

  try {
    const folderId = req.body.folderId ? parseInt(req.body.folderId, 10) : null;

    // Verify folder belongs to user if folderId is provided
    if (folderId) {
      const folder = await context.entities.Folder.findUnique({
        where: { id: folderId },
      });
      if (!folder || folder.userId !== context.user.id) {
        return res.status(400).json({ error: "Invalid folder" });
      }
    }

    const newFile = await context.entities.File.create({
      data: {
        name: req.file.originalname,
        mimeType: req.file.mimetype,
        size: req.file.size,
        localPath: req.file.path,
        folderId,
        userId: context.user.id,
      },
    });

    return res.json(newFile);
  } catch (error: any) {
    console.error("Upload error:", error);
    return res.status(500).json({ error: error.message || "Failed to save file metadata" });
  }
};

export const downloadFile = async (req: any, res: any, context: any) => {
  const { linkId } = req.params;
  const passwordQuery = req.query.password;

  try {
    const shareLink = await context.entities.ShareLink.findUnique({
      where: { id: linkId },
      include: {
        file: true,
      },
    });

    if (!shareLink) {
      return res.status(404).json({ error: "Share link not found" });
    }

    // Check expiration
    const isExpired = shareLink.expiresAt ? new Date() > new Date(shareLink.expiresAt) : false;
    if (isExpired) {
      return res.status(410).json({ error: "Share link has expired" });
    }

    // Check password
    if (shareLink.password && passwordQuery !== shareLink.password) {
      return res.status(401).json({ error: "Incorrect password" });
    }

    // Check if the actual file exists on disk
    if (!fs.existsSync(shareLink.file.localPath)) {
      return res.status(404).json({ error: "File not found on server disk" });
    }

    // Log the access
    const ipAddress =
      (req.headers["x-forwarded-for"] as string) ||
      req.ip ||
      req.socket.remoteAddress ||
      "unknown";
    const userAgent = req.headers["user-agent"] || "unknown";

    await context.entities.AccessLog.create({
      data: {
        fileId: shareLink.fileId,
        ipAddress,
        userAgent,
      },
    });

    // Send file
    res.setHeader("Content-Type", shareLink.file.mimeType);
    res.setHeader("Content-Length", shareLink.file.size);
    res.setHeader(
      "Content-Disposition",
      `attachment; filename="${encodeURIComponent(shareLink.file.name)}"`
    );

    return res.sendFile(shareLink.file.localPath);
  } catch (error: any) {
    console.error("Download error:", error);
    return res.status(500).json({ error: error.message || "Failed to download file" });
  }
};

