import React, { useState } from "react";
import { useQuery, getRootContents, createFolder, createShareLink } from "wasp/client/operations";
import { api } from "wasp/client/api";
import { logout } from "wasp/client/auth";
import { Link } from "react-router";
import "./Main.css";

export function MainPage() {
  const { data: contents, isLoading, error, refetch } = useQuery(getRootContents);

  // Folder creation state
  const [newFolderName, setNewFolderName] = useState("");
  const [creatingFolder, setCreatingFolder] = useState(false);
  const [folderError, setFolderError] = useState<string | null>(null);

  // File upload state
  const [selectedFile, setSelectedFile] = useState<File | null>(null);
  const [uploading, setUploading] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);

  // Share state
  const [sharingFileId, setSharingFileId] = useState<number | null>(null);
  const [sharingFileName, setSharingFileName] = useState<string>("");
  const [sharePassword, setSharingPassword] = useState("");
  const [shareExpires, setSharingExpires] = useState("");
  const [generatedLink, setGeneratedLink] = useState<string | null>(null);
  const [shareError, setShareError] = useState<string | null>(null);
  const [creatingShare, setCreatingShare] = useState(false);

  const handleCreateFolder = async (e: React.FormEvent) => {
    e.preventDefault();
    setFolderError(null);
    setCreatingFolder(true);

    if (!newFolderName.trim()) {
      setFolderError("Folder name is required");
      setCreatingFolder(false);
      return;
    }

    try {
      await createFolder({ name: newFolderName.trim(), parentId: null });
      setNewFolderName("");
      refetch();
    } catch (err: any) {
      console.error(err);
      setFolderError(err.message || "Failed to create folder");
    } finally {
      setCreatingFolder(false);
    }
  };

  const handleFileUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    setUploadError(null);
    setUploading(true);

    if (!selectedFile) {
      setUploadError("Please select a file to upload");
      setUploading(false);
      return;
    }

    const formData = new FormData();
    formData.append("file", selectedFile);

    try {
      await api.post("api/upload", { body: formData });
      setSelectedFile(null);
      // Reset the file input field
      const fileInput = document.getElementById("file-upload-input") as HTMLInputElement;
      if (fileInput) fileInput.value = "";
      refetch();
    } catch (err: any) {
      console.error(err);
      setUploadError("Failed to upload file");
    } finally {
      setUploading(false);
    }
  };

