                    type="submit"
                    data-testid="create-share-link-btn"
                    className="button button-filled"
                    style={{ width: "100%", backgroundColor: "#ffaa00" }}
                    disabled={creatingShare}
                  >
                    {creatingShare ? "Generating..." : "Create Link"}
                  </button>
